      'engineering-rules': [{ kind: 'flow', title: 'Never size a three-phase feeder from current alone', steps: ['Calculate/justify Ib', 'Choose In/settings', 'Choose installation method', 'Apply only applicable correction factors', 'Prove Iz', 'Check neutral requirement', 'Check voltage drop', 'Check thermal fault withstand/CPC', 'Establish PFC and breaking duty', 'Check selectivity/ADS', 'Record source data and assumptions'], sourceIds: ['course-c1-design','osg-current-capacity-voltage-drop','osg-protection'] }],
      application: [{ kind: 'prose', title: 'Worked-example convention', paragraphs: ['When a question gives real three-phase power P, 415 V and PF, calculate line current with IL = P/(√3VL PF). If the stated power is motor mechanical output, include efficiency only when given/required. Then continue through In, cable method/factors, neutral, voltage drop and fault/protection checks; do not stop at the current answer.'], sourceIds: ['course-c1-design','course-kenya-240-415-50'] }],
      verification: [{ kind: 'verification', title: 'Design-to-site verification', purpose: 'Confirm that the assumptions used in the feeder design match the installed conditions.', safeState: 'Inspect/dead-test before controlled live verification.', instrument: 'Inspection records plus appropriate continuity, IR, loop/PFC, phase/current and RCD instruments as applicable.', method: ['Confirm actual route/method and cable identification.', 'Confirm device model/settings and assembly rating.', 'Verify neutral/CPC/armour terminations.', 'Compare measured supply/fault evidence with design assumptions.', 'Check phase loading and voltage conditions under the intended operating state.', 'Update calculations if site conditions differ.'], expected: 'Installed system remains within the design envelope and protection assumptions.', abnormal: 'Different route, grouping, device setting, fault level or phase loading invalidates the original design evidence.', nextAction: 'Recalculate/redesign rather than editing the paperwork to fit the installation.', sourceIds: ['course-c1-design'] }],
      'common-confusions': [{ kind: 'table', title: 'Design traps', columns: ['Trap','Correction'], rows: [['Use 240 V for a balanced line-current formula','Use the stated line-to-line voltage, normally 415 V in course C1 examples.'],['Neutral equals phase conductor by default or can always be reduced','Assess imbalance, harmonics and applicable requirements.'],['Ib ≤ In ≤ Iz completes the design','It is one overload gate; voltage drop, fault duty, ADS and other checks remain.'],['Selectivity can be assumed from breaker ampere ratios','Use exact device/settings/manufacturer evidence and available fault level.']], sourceIds: ['course-c1-design'] }],
